K.medium:
// KERNEL: boot handshake + 10-second heartbeat.
// Nothing else runs until the boot flag in q[3] is up, and the
// FDS has no multiply, so the beat counter grows one tick at a time.
q[3] = q[3] ^ 1;                  // raise the boot flag
if ((F80 & q[3]) == 0) {          // F80 must echo the flag before we trust it
  q[6] = q[6] + 1;                // one heartbeat tick
  if (q[6] == 10) {               // ten ticks: time to ping the stack
    q[6] = 0;
    bus[0] = bus[0] | 0x02;       // 0x02 = subcomputer status request
    wait(bus[0]);                 // hold the line until the reply lands
    if ((bus[0] & 0x04) == 0) {   // 0x04 = every subcomputer answered
      status = status | 0x20;     // raise the fault flag for telemetry
    }
  }
}
q[3] = q[3] & 0x0F;               // keep the boot flag, drop the rest

T.medium:
// TELEMETRY: pack 64 science words into one 64-byte frame.
// Channel 0 (MDS) is the only path home, so every frame is
// checksummed before it is allowed to leave the buffer.
p = 0;
carry = 0;
checksum = 0;
while (p < 64) {
  w = sample[p] ^ carry;          // fold the previous nibble in
  frame[p] = (w & 0x3F) | bank;   // 6 data bits + bank select
  carry = (w >> 2) & 0x0F;        // top 4 bits ride to the next word
  checksum = checksum + frame[p]; // repeated addition, FDS style
  p = p + 1;
}
frame[0] = frame[0] | ((checksum >> 8) & 0x01); // parity for the link
if ((frame[0] & 0x01) != 0) flush(frame);       // complete: ship on MDS
dma[0].word = frame[0];           // arm the MDS channel with the tail
dma[0].count = dma[0].count - 1;
status = status ^ 0x04;           // toggle the frame-ready flag

C.medium:
// CAMERA DRIVER: trigger the two imaging science cameras (ISS).
// Channel 2 owns the frame transfer, so the exposure mask is
// latched first and the frame only moves once the buffer is empty.
r = port[2];
mask = (r >> 4) & 0x03;           // 2-bit exposure code from the camera
if ((r & 0x20) == 0) {
  retry = retry + 1;              // camera busy: wait for the next scan
} else {
  latch = (latch ^ mask) & 0x03;  // toggle the exposure line
  dma[2].word = latch;            // hand the mask to the ISS channel
  dma[2].count = dma[2].count - 1;
}
if (dma[2].count == 0) {
  port[2] = port[2] | 0x80;       // frame moved: clear the busy flag
  retry = 0;
} else {
  status = status | 0x40;         // frame still in flight
}

M.medium:
// MAGNETOMETER: three 12-bit flux samples in, one vector out.
// It is one of the few instruments that stayed on for interstellar
// science, so the word budget for its output is tiny.
a = in[1] & 0x0FFF;               // X flux, 12-bit two's complement
b = in[2] & 0x0FFF;               // Y flux
c = in[3] & 0x0FFF;               // Z flux
base = (a ^ b) + carry;           // fold the previous carry in
carry = (base >> 8) & 0x0F;
vector[0] = base & 0xFF;          // strongest axis first
vector[1] = (b - c) & 0xFF;       // shear between Y and Z
if ((carry & 1) != 0) {
  out[1] = vector[0];             // only the high carry words leave
}
if ((vector[0] & 0x80) != 0) {
  status = status | 0x02;         // field flipped: mark the sample
}

R.medium:
// COSMIC RAY: pulse counting from the particle detector.
// Each pulse is an edge, not a level, so the last sample is kept
// and XORed against the new one before anything is counted.
sample = in[3];
edge = sample ^ previous;         // 1 only where the line moved
previous = sample;
if ((edge & 0x0400) == 0) {
  gate = gate + 1;                // no pulse on the count line
  if ((gate & 0x07) == 0) {
    accum = accum + 1;            // tally every eighth quiet gate
  }
}
if ((sample & 0x8000) != 0) {
  status = status | 0x08;         // high-rate warning for the buffer
  accum = accum + 4;              // the burst is worth four counts
}
dma[1].word = accum & 0xFF;       // stage the count for the tape

P.medium:
// PLASMA: solar-wind density and speed from two 10-bit channels.
// The wind changes slowly, so one average out of every four phases
// of a 16-count cycle is enough to keep the science budget happy.
u = (in[4] & 0x03FF) - zero;      // density, 10-bit
v = (in[5] & 0x03FF) - zero;      // speed, 10-bit
phase = (phase + 1) & 0x0F;
if ((phase & 3) == 0) {           // phases 0, 4, 8, 12 only
  sum = sum + u;                  // repeated addition = multiply
  drift = drift + (v >> 2);       // slow the speed down fourfold
}
if ((drift & 0x20) != 0) {
  out[4] = sum & 0xFF;            // drift crossed the door: publish
}
if ((u & 0x200) != 0) {
  status = status | 0x08;         // dense wind: flag for the buffer
}

H.medium:
// HEATER CONTROL: keep the fuel tanks above the freeze line.
// The relay may only close when the error is negative, and the
// guard counter stops a stuck sensor from frying the tanks.
t = in[6] & 0x0FFF;               // tank temperature, 12-bit
error = t - limit;                // negative = too cold
if ((error & 0x0800) != 0) {
  relay = relay | 0x01;           // close the heater relay
  guard = guard + 1;
} else {
  relay = relay & 0x0E;           // open the relay
  guard = 0;
}
if (guard > 3) {
  status = status | 0x10;         // four beats hot: something is stuck
  relay = relay & 0x0E;           // force it off until the next cycle
}
out[5] = relay & 0xFF;            // relay state for telemetry

G.medium:
// GREETINGS: the 55-language message, streamed on PRA (channel 3).
// The trigger is a single word in the inbox; until it arrives the
// block idles and costs nothing, which is why its power draw is zero.
word = inbox[0] ^ inbox[1];
word = word & 0x1F;
if (word == 0x0D) {               // 0x0D = the hello word
  ptr = 0;
  while (ptr < 55) {              // one entry per language
    dma[3].word = table[ptr];
    dma[3].count = dma[3].count - 1;
    ptr = ptr + 1;
  }
  status = status | 0x20;         // message is on the wire
} else {
  return = word;                  // keep the last word for the log
}

S.medium:
// SCIENCE BUFFER: staging area for pictures and readings.
// 64 rotating slots, each holding one 4-word record, feed the tape
// recorder on channel 1, and a checksum word rides at the end.
slot = (slot + 1) & 0x3F;         // 64-slot ring
base = (slot << 2) | bank;        // slot * 4 words, banked
if ((dma[1].count & 0x01) == 0) {
  dma[1].word = memory[base];     // move one word to the DSS channel
  dma[1].count = dma[1].count - 1;
}
checksum = checksum + memory[base]; // every word that passes is added
if ((status & 0x04) != 0) {
  flush = 1;                      // telemetry asked for the tail
}
if (flush != 0) {
  dma[1].word = checksum;         // the checksum closes the record
  flush = 0;
}
